{"packet_id":"D073-02","doc_id":"D073","jurisdiction":"San Diego, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"San Diego just cause termination notice, relocation assistance and right to re-lease","requirement":"For no-fault just cause terminations, a landlord must give 30 or 60 days' written notice, provide relocation assistance equal to two months' actual rent (three months for senior or disabled tenants), and offer the displaced tenant a chance to re-lease.","key_value":"2 months' actual rent; 3 months if senior or disabled","coverage_conditions":"Tenancies in residential rental properties subject to Division 7 of Chapter 9, Article 8; the lease-notice requirement applies to tenancies commencing or renewed on or after June 24, 2023.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Residential rental property subject to Division 7"},"exemptions":null,"penalty":"Landlord failing to provide relocation assistance is liable for not less than three times the required relocation assistance plus actual damages; wrongful eviction damages not less than three times actual economic damages; noncompliance renders void any termination notice.","effective_date":"2023-06-24","citation":"San Diego Mun. Code § 98.0706","quoted_span":"Unless section 98.0706(c)(1)(A)(ii) applies, the direct payment to the tenant shall be in an amount equal to two months of actual rent under the tenant’s lease in effect at the date of the notice.","interaction":"Relocation assistance is credited against any other relocation assistance required by federal, state, or other local law.","confidence":0.95,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D073-02","doc_id":"D073","jurisdiction":"San Diego, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"San Diego buyout agreement requirements","requirement":"Before making a buyout offer a landlord must give each tenant a written disclosure of specified rights, provide executed copies, and use a written agreement with required bold 14-point statements; a buyout for less than the relocation assistance owed is void.","key_value":"Buyout must exceed relocation assistance (2 months' rent; 3 if senior or disabled)","coverage_conditions":"Tenants in residential rental properties subject to Division 7 of Chapter 9, Article 8 of the San Diego Municipal Code.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Residential rental property subject to Division 7"},"exemptions":null,"penalty":"A buyout agreement that does not strictly comply with the requirements is void; any term purporting to waive or limit a tenant's rights under the section is contrary to public policy, unenforceable and void.","effective_date":"2023-06-24","citation":"San Diego Mun. Code § 98.0707","quoted_span":"Buyout agreements must be for an amount that is greater than the amount of relocation assistance available to the tenant in section 98.0706(c). A buyout agreement for less than the amount of relocation assistance owed to the tenant violates this Division and is void.","interaction":null,"confidence":0.95,"conflict_flag":false,"conflict_note":null}
